import { z } from "zod";
const SESSION_STATE_VERSION = 1;
const SessionStatusSchema = z.enum([
  "active",
  "paused",
  "completed",
  "failed",
  "exited",
  "cleanup-failed"
]);
const SessionAccessModeSchema = z.enum(["read-only", "write-access"]);
const SessionViewportSchema = z.object({
  width: z.number().int().min(1),
  height: z.number().int().min(1)
});
const ProviderStateSchema = z.object({
  name: z.string(),
  sessionId: z.string(),
  recordingUrl: z.string().url().optional()
});
const SessionStateFileSchema = z.object({
  version: z.literal(SESSION_STATE_VERSION),
  port: z.number().int().min(0).max(65535),
  pid: z.number().int().optional(),
  cdpEndpoint: z.string().url().optional(),
  session: z.string().min(1),
  startedAt: z.string().datetime({ offset: true }),
  status: SessionStatusSchema.optional(),
  mode: SessionAccessModeSchema.default("write-access"),
  viewport: SessionViewportSchema.optional(),
  stayOpenOnSuccess: z.boolean().optional(),
  provider: ProviderStateSchema.optional(),
  daemonSocketPath: z.string().optional()
});
function formatIssues(error) {
  return error.issues.map((issue) => {
    const path = issue.path.join(".") || "root";
    return `${path}: ${issue.message}`;
  }).join("; ");
}
function parseSessionStateData(rawState, source) {
  const parsed = SessionStateFileSchema.safeParse(rawState);
  if (!parsed.success) {
    throw new Error(
      `Session state at ${source} is invalid: ${formatIssues(parsed.error)}`
    );
  }
  const { version: _version, ...state } = parsed.data;
  return state;
}
function parseSessionStateContent(content, source) {
  let rawState;
  try {
    rawState = JSON.parse(content);
  } catch (error) {
    throw new Error(
      `Session state at ${source} is not valid JSON: ${error instanceof Error ? error.message : String(error)}`
    );
  }
  return parseSessionStateData(rawState, source);
}
function serializeSessionState(state) {
  return SessionStateFileSchema.parse({
    version: SESSION_STATE_VERSION,
    ...state
  });
}
export {
  ProviderStateSchema,
  SESSION_STATE_VERSION,
  SessionAccessModeSchema,
  SessionStateFileSchema,
  SessionStatusSchema,
  SessionViewportSchema,
  parseSessionStateContent,
  parseSessionStateData,
  serializeSessionState
};
